                    }):Play()
                end)
                
                closeButton.MouseLeave:Connect(function()
                    TweenService:Create(closeCircle, TweenInfo.new(0.2), {
                        BackgroundTransparency = 0.3,
                        BackgroundColor3 = Colors.surfaceLight
                    }):Play()
                    TweenService:Create(closeIcon, TweenInfo.new(0.2), {
                        ImageColor3 = Colors.textSecondary
                    }):Play()
                end)
            end
            
            keyInput.Focused:Connect(function()
                TweenService:Create(inputStroke, TweenInfo.new(0.2), {
                    Color = Colors.primary,
                    Thickness = 2,
                    Transparency = 0
                }):Play()
            end)
            
            keyInput.FocusLost:Connect(function()
                TweenService:Create(inputStroke, TweenInfo.new(0.2), {
                    Color = Colors.border,
                    Thickness = 1,
                    Transparency = 0.5
                }):Play()
            end)
            
            contentContainer.Position = UDim2.new(0.5, 0, 0.5, 50)
            contentContainer.GroupTransparency = 1
            
            task.wait(0.1)
            
            TweenService:Create(contentContainer, TweenInfo.new(0.6, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Position = UDim2.new(0.5, 0, 0.5, 0),
                GroupTransparency = 0
            }):Play()
            
            local function updateScaling()
                local newViewportSize = workspace.CurrentCamera.ViewportSize
                local newScaleFactor = math.min(newViewportSize.X / baseWidth, newViewportSize.Y / baseHeight)
                newScaleFactor = math.clamp(newScaleFactor, 0.4, 1.2)
                
                local newAvailableHeight = newViewportSize.Y * 0.9
                local newAvailableWidth = newViewportSize.X * 0.9
                
                local newContainerWidth = math.max(baseContainerWidth * newScaleFactor, 320)
                local newContainerHeight = math.max(baseContainerHeight * newScaleFactor, 440)
                
                newContainerWidth = math.min(newContainerWidth, newAvailableWidth)
                newContainerHeight = math.min(newContainerHeight, newAvailableHeight)
                newContainerWidth = math.min(newContainerWidth, 650)
                newContainerHeight = math.min(newContainerHeight, 620)
                
                local newInputHeight = math.max(newContainerHeight * 0.11, 45)
                local newButtonHeight = math.max(newContainerHeight * 0.10, 42)
                
                local newTitleHeight = newContainerHeight * 0.15
                local newSubtitleHeight = 25
                local newGapTitleToSubtitle = -25
                local newGapSubtitleToInput = 25
                local newGapInputToVerify = 15
                local newGapVerifyToGetKey = 15
                
                local newMainContentHeight = newTitleHeight + newGapTitleToSubtitle + newSubtitleHeight + 
                                            newGapSubtitleToInput + newInputHeight + newGapInputToVerify + 
                                            newButtonHeight + newGapVerifyToGetKey + newButtonHeight
                
                local newStartY = (newContainerHeight - newMainContentHeight) / 2
                newStartY = newStartY + 20
                newStartY = math.max(newStartY, newContainerHeight * 0.08)
                
                local newTopMargin = newStartY
                local newSubtitleY = newTopMargin + newTitleHeight + newGapTitleToSubtitle
                local newInputY = newSubtitleY + newSubtitleHeight + newGapSubtitleToInput
                local newVerifyY = newInputY + newInputHeight + newGapInputToVerify
                local newGetLinkY = newVerifyY + newButtonHeight + newGapVerifyToGetKey
                
                local newStatusY = newContainerHeight * 0.85
                
                local newTitleSize = math.clamp(math.floor(64 * newScaleFactor), 28, 72)
                local newSubtitleSize = math.clamp(math.floor(14 * newScaleFactor), 10, 16)
                local newInputTextSize = math.clamp(math.floor(16 * newScaleFactor), 12, 18)
                local newButtonTextSize = math.clamp(math.floor(15 * newScaleFactor), 11, 17)
                
                local newElementWidth = math.min(math.max(newContainerWidth * 0.75, 280), 450)
                local newElementHalfWidth = newElementWidth / 2
                
                TweenService:Create(contentContainer, TweenInfo.new(0.3), {
                    Size = UDim2.new(0, newContainerWidth, 0, newContainerHeight)
                }):Play()
                
                if titleLabel then 
                    titleLabel.TextSize = newTitleSize
                    TweenService:Create(titleLabel, TweenInfo.new(0.3), {
                        Size = UDim2.new(1, 0, 0, newTitleHeight),
                        Position = UDim2.new(0, 0, 0, newTopMargin)
                    }):Play()
                end
                
                if subtitleLabel then 
                    subtitleLabel.TextSize = newSubtitleSize
                    TweenService:Create(subtitleLabel, TweenInfo.new(0.3), {
                        Position = UDim2.new(0, 0, 0, newSubtitleY)
                    }):Play()
                end
                
                if keyInput then keyInput.TextSize = newInputTextSize end
                if verifyText then verifyText.TextSize = newButtonTextSize end
                if getLinkText then getLinkText.TextSize = newButtonTextSize end
                if statusText then statusText.TextSize = math.clamp(math.floor(12 * newScaleFactor), 9, 14) end
                
                if inputContainer then
                    TweenService:Create(inputContainer, TweenInfo.new(0.3), {
                        Size = UDim2.new(0, newElementWidth, 0, newInputHeight),
                        Position = UDim2.new(0.5, -newElementHalfWidth, 0, newInputY)
                    }):Play()
                end
                
                if verifyButton then
                    TweenService:Create(verifyButton, TweenInfo.new(0.3), {
                        Size = UDim2.new(0, newElementWidth, 0, newButtonHeight),
                        Position = UDim2.new(0.5, -newElementHalfWidth, 0, newVerifyY)
                    }):Play()
                end
                
                if getLinkButton then
                    TweenService:Create(getLinkButton, TweenInfo.new(0.3), {
                        Size = UDim2.new(0, newElementWidth, 0, newButtonHeight),
                        Position = UDim2.new(0.5, -newElementHalfWidth, 0, newGetLinkY)
                    }):Play()
                end
                
                if statusText then
                    TweenService:Create(statusText, TweenInfo.new(0.3), {
                        Position = UDim2.new(0.05, 0, 0, newStatusY)
                    }):Play()
                end
                
                if statusBar then
                    TweenService:Create(statusBar, TweenInfo.new(0.3), {
                        Position = UDim2.new(0.5, 0, 0, newStatusY + 35)
                    }):Play()
                end
            end
            
            workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(updateScaling)
            
            self.gui.Parent = game:GetService("CoreGui")
            
            self.gui.AncestryChanged:Connect(function(_, parent)
                if parent == nil then
                    local blur = Lighting:FindFirstChild("JunkieUIBlur")
                    if blur then blur:Destroy() end
                end
            end)

            
            self.showSuccess = function(self, message)
                if not self.elements then return end
                
                local container = self.elements.container
                local loadingOverlay = container:FindFirstChild("LoadingOverlay")
                
                if loadingOverlay then
                    local mainContainer = loadingOverlay:FindFirstChild("MainContainer")
                    local spinnerContainer = mainContainer and mainContainer:FindFirstChild("SpinnerContainer")
                    local loadingText = mainContainer and mainContainer:FindFirstChild("LoadingText")
                    local hintText = mainContainer and mainContainer:FindFirstChild("HintText")
                    
                    if spinnerContainer then
                        TweenService:Create(
                            spinnerContainer,
                            TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                            {Rotation = 0}
                        ):Play()
                        
                        for _, child in ipairs(spinnerContainer:GetChildren()) do
                            if child:IsA("Frame") then
                                TweenService:Create(
                                    child,
                                    TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                                    {BackgroundTransparency = 1}
                                ):Play()
                                
                                local stroke = child:FindFirstChildOfClass("UIStroke")
                                if stroke then
                                    TweenService:Create(
                                        stroke,
                                        TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
                                        {Transparency = 1}
                                    ):Play()
                                end
                            end
                        end
                        
                        task.wait(0.25)
                        
                        local checkmarkContainer = Instance.new("Frame")
                        checkmarkContainer.Name = "CheckmarkContainer"
                        checkmarkContainer.BackgroundTransparency = 1
                        checkmarkContainer.Size = UDim2.new(1, 0, 1, 0)
                        checkmarkContainer.Position = UDim2.new(0, 0, 0, 0)
                        checkmarkContainer.Parent = mainContainer
                        
                        local successCircle = Instance.new("Frame")
                        successCircle.Name = "SuccessCircle"
                        successCircle.BackgroundColor3 = Colors.success
                        successCircle.BackgroundTransparency = 1
                        successCircle.Size = UDim2.new(0, 80, 0, 80)
                        successCircle.Position = UDim2.new(0.5, 0, 0, 20)
                        successCircle.AnchorPoint = Vector2.new(0.5, 0)
                        successCircle.Parent = checkmarkContainer
                        
                        local successCorner = Instance.new("UICorner")
                        successCorner.CornerRadius = UDim.new(1, 0)
                        successCorner.Parent = successCircle
                        
                        local checkmark = Instance.new("TextLabel")
                        checkmark.Name = "Checkmark"
                        checkmark.BackgroundTransparency = 1
                        checkmark.Size = UDim2.new(1, 0, 1, 0)
                        checkmark.Position = UDim2.new(0, 0, 0, -4)
                        checkmark.Font = Enum.Font.GothamBold
                        checkmark.Text = "✓"
                        checkmark.TextColor3 = Color3.fromRGB(255, 255, 255)
                        checkmark.TextSize = 0
                        checkmark.TextTransparency = 1
                        checkmark.Parent = successCircle
                        
                        TweenService:Create(
                            successCircle,
                            TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
                            {BackgroundTransparency = 0.15, Size = UDim2.new(0, 90, 0, 90)}
                        ):Play()
                        
                        task.wait(0.15)
                        TweenService:Create(
                            checkmark,
                            TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
                            {TextSize = 52, TextTransparency = 0}
                        ):Play()
                    end
                    
                    if loadingText then
                        task.wait(0.1)
                        loadingText.Text = message or "Verified!"
                        loadingText.TextColor3 = Colors.success
                    end
                    
                    if hintText then
                        hintText.Text = "Starting script"
                        hintText.TextColor3 = Colors.success
                    end
                end
                
                task.wait(0.8)
            end
            
            self.updateStatus = function(self, message, color, duration)
                local statusText = self.elements.statusText
                local statusBar = self.elements.statusBar
                
                if statusText then
                    statusText.Text = message
                    statusText.TextColor3 = color or Colors.textSecondary
                    statusText.Visible = true
                    
                    if statusBar then
                        TweenService:Create(statusBar, TweenInfo.new(0.3), {
                            BackgroundColor3 = color or Colors.primary,
                            Size = UDim2.new(0, 200, 0, 2)
                        }):Play()
                    end
                    
                    if duration and duration > 0 then
                        task.delay(duration, function()
                            if statusText and statusText.Text == message then
                                statusText.Visible = false
                                if statusBar then
                                    TweenService:Create(statusBar, TweenInfo.new(0.3), {
                                        Size = UDim2.new(0, 0, 0, 2)
                                    }):Play()
                                end
                            end
                        end)
                    end
                end
            end
            
            self.setButtonLoading = function(self, button, text, loading)
                local buttonText = button:FindFirstChild("ButtonText")
                if not buttonText then return end
                
                if loading then
                    buttonText.Text = text
                    button.Active = false
                else
                    buttonText.Text = text
                    button.Active = true
                end
            end
            
            self.shakeInput = function(self)
                local frame = self.elements.inputFrame
                if not frame then return end
                
                local orig = frame.Position
                
                for i = 1, 3 do
                    TweenService:Create(frame, TweenInfo.new(0.05), {
                        Position = UDim2.new(orig.X.Scale, orig.X.Offset - 10, orig.Y.Scale, orig.Y.Offset)
                    }):Play()
                    task.wait(0.05)
                    TweenService:Create(frame, TweenInfo.new(0.05), {
                        Position = UDim2.new(orig.X.Scale, orig.X.Offset + 10, orig.Y.Scale, orig.Y.Offset)
                    }):Play()
                    task.wait(0.05)
                end
                
                frame.Position = orig
            end
            
            self.animateSuccess = function(self)
            end
            
            self.close = function(self)
                if not self.gui then return end
                getgenv().UI_CLOSED = true
                local container = self.elements.container
                local backdrop = self.elements.backdrop
                local blur = Lighting:FindFirstChild("JunkieUIBlur")
                
                TweenService:Create(container, TweenInfo.new(0.3), {
                    GroupTransparency = 1
                }):Play()
                
                TweenService:Create(backdrop, TweenInfo.new(0.3), {
                    BackgroundTransparency = 1
                }):Play()
                
                task.wait(0.3)
                
                if blur then blur:Destroy() end
                self.gui:Destroy()
                self.gui = nil
            end
            
